def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    groups = []  # Initialize list to store individual strings

    stack = []  # Initialize stack to keep track of opening parentheses
    start = 0  # Initialize variable to keep track of the start index of a group

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)  # Push index of opening parenthesis to stack
        elif char == ')':
            start = stack.pop()  # Pop index of opening parenthesis from stack
            groups.append(paren_string[start:i+1])  # Extract group and add to list

    return groups

